import{_ as i,o as a,c as o,a2 as e}from"./chunks/framework.CdvW4CUT.js";const s=JSON.parse('{"title":"伺服規定  (2021-11-25)","description":"","frontmatter":{},"headers":[],"relativePath":"rule/history/20211125/index.md","filePath":"rule/history/20211125.md"}'),r={name:"rule/history/20211125/index.md"};function t(u,l,n,h,c,d){return a(),o("div",null,[...l[0]||(l[0]=[e('<h1 id="伺服規定-2021-11-25" tabindex="-1">伺服規定 (2021-11-25) <a class="header-anchor" href="#伺服規定-2021-11-25" aria-label="Permalink to &quot;伺服規定  (2021-11-25)&quot;">​</a></h1><h4 id="當您加入伺服器遊玩-即視為您同意並遵守此規定" tabindex="-1">當您加入伺服器遊玩，即視為您同意並遵守此規定 <a class="header-anchor" href="#當您加入伺服器遊玩-即視為您同意並遵守此規定" aria-label="Permalink to &quot;當您加入伺服器遊玩，即視為您同意並遵守此規定&quot;">​</a></h4><ul><li>本規定適用範圍 : Java 伺服器 / Discord『💻伺服同步頻道』</li><li>最後更新時間 : 2021/11/25</li></ul><h3 id="請勿影響其他玩家遊玩" tabindex="-1">請勿影響其他玩家遊玩 <a class="header-anchor" href="#請勿影響其他玩家遊玩" aria-label="Permalink to &quot;請勿影響其他玩家遊玩&quot;">​</a></h3><ul><li>破壞建築、偷東西、騷擾、詐欺、惡意誤導、無意義LAG機...等影響他人的行為 <ul><li>基本上，在路上看到人造建築與箱子不要任意去亂碰</li></ul></li><li>嚴禁以非正當管道取得畫作 <ul><li>非正當管道係指未經作者同意逕自盜印或複製畫作</li></ul></li></ul><h3 id="請勿在公眾聊天頻道違反下列規定" tabindex="-1">請勿在公眾聊天頻道違反下列規定 <a class="header-anchor" href="#請勿在公眾聊天頻道違反下列規定" aria-label="Permalink to &quot;請勿在公眾聊天頻道違反下列規定&quot;">​</a></h3><ul><li>包含但不限於 : 洗頻 / 傳送釣魚連結 / 散播個人資料 / 吵架或謾罵 / 散播限制級圖片或言論...</li><li>範圍認定 <ul><li>Minecraft伺服器內『公眾聊天室』 <ul><li>遊戲內的私訊、社區頻道...，皆無任何規範，玩家皆可自由利用，沒有任何限制</li><li>伺服不會記錄或儲存任何非公眾聊天的紀錄，請玩家自行保存</li></ul></li><li>Discord『💻伺服同步頻道』(不包含其他Discord頻道) <ul><li>包含您使用Discord帳號在『💻伺服同步頻道』的發言</li></ul></li></ul></li></ul><h3 id="嚴禁使用外掛功能-遊戲bug" tabindex="-1">嚴禁使用外掛功能/遊戲BUG <a class="header-anchor" href="#嚴禁使用外掛功能-遊戲bug" aria-label="Permalink to &quot;嚴禁使用外掛功能/遊戲BUG&quot;">​</a></h3><ul><li>以下幾種模組與客戶端<font color="green"><b>可使用</b></font><ul><li>一般模組 <ul><li>小地圖、整理背包、光影</li><li>藍圖(Litematica)、連點 不可用於活動或使用腳本運行</li></ul></li><li>客戶端 <ul><li>LunarClient、Badlion</li></ul></li><li>其餘未明載之模組或客戶端若要使用，建議事先詢問客服是否允許</li></ul></li><li>以下模組或功能<font color="red"><b>嚴禁使用</b></font>(包括但不限於) <ul><li>任何具外掛或透視功能的材質包/模組</li><li>使用<font color="red"><b>含有外掛功能</b></font>之客戶端遊玩 (不論是否開啟外掛功能)</li><li>飛行、自動建設、自動戰鬥、KillAura...</li></ul></li><li>遊戲BUG / 伺服異常 / 插件漏洞 <ul><li>原版BUG : TNT、鐵軌、地毯複製機... <ul><li>認定標準 : 『遊戲機制』和『實際玩法』不一致時，以遊戲機制為主</li></ul></li><li>利用或從中獲取利益</li></ul></li><li>若有上述之情事發生，伺服人員擁有主動介入處置之權利 <ul><li>未明載但屬本項規定所涵蓋之事項，將由伺服人員認定及處置</li><li>若玩家知悉上述之情事發生，請即時利用<a href="/contact/">客服</a>通報，切勿知情不報 <ul><li>知情不報者經伺服人員查獲時將一併進行處置</li></ul></li></ul></li></ul><h3 id="請勿開分身或使用vpn遊玩" tabindex="-1">請勿開分身或使用VPN遊玩 <a class="header-anchor" href="#請勿開分身或使用vpn遊玩" aria-label="Permalink to &quot;請勿開分身或使用VPN遊玩&quot;">​</a></h3><ul><li>若有這類需求，請務必主動利用<a href="/contact/">客服</a>向伺服人員詢問或提出申請</li><li>違反本項規定將依照伺服人員之認定進行處置</li></ul><h3 id="嚴禁影響伺服運作" tabindex="-1">嚴禁影響伺服運作 <a class="header-anchor" href="#嚴禁影響伺服運作" aria-label="Permalink to &quot;嚴禁影響伺服運作&quot;">​</a></h3><ul><li>嚴禁有任何影響伺服運作之行為或預謀 <ul><li>包含但不限於以網路或電磁紀錄等方式影響伺服運作</li><li>情節嚴重之抄襲或模仿，且經比對後能客觀辨認為抄襲而非原創之內容</li><li>為確保伺服運作的穩定，此類個案的處置依據將可能溯及既往</li><li>必要時，伺服人員需向全體玩家公開判決依據及理由</li><li>若有嚴重危害而致違法疑慮者，將不排除採取法律途徑</li></ul></li><li>若有上述之情事發生，伺服人員擁有主動介入處置之權利 <ul><li>未明載但屬本項規定所涵蓋之事項，將由伺服人員認定及處置</li></ul></li></ul><h2 id="處分-調解與上訴" tabindex="-1">處分/調解與上訴 <a class="header-anchor" href="#處分-調解與上訴" aria-label="Permalink to &quot;處分/調解與上訴&quot;">​</a></h2><h3 id="處分方式" tabindex="-1">處分方式 <a class="header-anchor" href="#處分方式" aria-label="Permalink to &quot;處分方式&quot;">​</a></h3><ul><li>違反上述伺服規定，伺服有權利對玩家進行以下的處分 <ul><li>暫停或終止玩家在本伺服的遊玩權限</li><li>暫時限制玩家在遊戲聊天室發言的權利</li><li>刪除或回溯玩家在本伺服的遊玩紀錄</li></ul></li></ul><h3 id="案件調解" tabindex="-1">案件調解 <a class="header-anchor" href="#案件調解" aria-label="Permalink to &quot;案件調解&quot;">​</a></h3><ul><li>主要適用於『玩家與玩家之間的檢舉』</li><li>主要由<font color="dark_red">被檢舉人</font>親自向<font color="blue">檢舉人</font>提出，伺服方不會主動介入 <ul><li><font color="dark_red">被檢舉人</font>也可由<a href="/contact/">客服</a>告知伺服人員，請伺服人員作為第三方協助處理</li></ul></li><li>調解期限 : <font color="blue">檢舉人</font>提出檢舉後，檢舉『還原完成』前 <ul><li>若在還原完成後才提出調解，需由伺服人員同意才可受理</li></ul></li><li>調解流程 <ul><li>若玩家在檢舉後，<font color="dark_red">被檢舉人</font>主動聯繫<font color="blue">檢舉人</font>相關調解事宜，可暫緩檢舉處理 <ul><li><font color="blue">檢舉人</font>有拒絕調解的權力</li></ul></li><li>請<font color="blue">檢舉人</font>在檢舉頻道告知伺服人員此檢舉在調解中</li><li>由雙方自行私下調解(或由伺服人員協助雙方)相關補償或處理方式</li><li>若調解成功，該檢舉將可撤銷，視為此案件未曾發生過</li></ul></li></ul><h3 id="案件上訴" tabindex="-1">案件上訴 <a class="header-anchor" href="#案件上訴" aria-label="Permalink to &quot;案件上訴&quot;">​</a></h3><ul><li>玩家權利上訴 <ul><li>玩家可在處分確定後由<a href="/contact/">客服</a>詢問/調解/上訴 <ul><li>上訴期限 : 判決確定後一個月內</li></ul></li></ul></li><li>處分資料 <ul><li>資料係指:處分依據與解釋判決 <ul><li>帶有個人隱私之內容需消去處理<br> (例如:IP / 座標 / 私人檢舉...)</li></ul></li><li>當事人有權利詢問與要求伺服人員提供資料<br> 而伺服人員有義務回覆並向當事人提供與解釋</li><li>雙方皆有權利向全體玩家公開資料以接受公評</li></ul></li></ul><h2 id="備註" tabindex="-1">備註 <a class="header-anchor" href="#備註" aria-label="Permalink to &quot;備註&quot;">​</a></h2><ol><li>伺服處分以帳號與IP為準，請務必保管好個人帳號(切勿外借給任何人，若發生任何狀況須自行承擔責任)，不接受任何因個人因素導致之理由作為要求解除處分之依據</li><li>若發現有玩家有違反以上規定時，請即時利用<a href="/contact/">客服</a>，切勿知情不報</li><li>若對於規定有任何疑慮或意見，請利用<a href="/contact/">客服</a>主動詢問伺服人員</li><li>有關『風平浪靜 Discord群組』的相關規定，目前是由管理員自行認定與裁決，不會影響遊玩權限<br> (『💻同步頻道』除外，<a href="#請勿在公眾聊天頻道違反下列規定">同步頻道規定</a>)</li></ol>',22)])])}const b=i(r,[["render",t]]);export{s as __pageData,b as default};
